package com.codeguardian.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; @Entity @Table(name="system_configs") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class SystemConfig{@Id @Column(name="config_key",length=100)String key;@Column(name="config_value",columnDefinition="TEXT")String value;LocalDateTime updatedAt;@PrePersist @PreUpdate void update(){updatedAt=LocalDateTime.now();}}
